const out = [];
const microQ = [];
const enqueue = (fn) => microQ.push(fn);
// async/await desugars to: run synchronously up to the first await, then
// schedule each post-await continuation as its own microtask.
function task() {
  out.push('start');                 // body before the first await runs synchronously
  enqueue(() => {                     // resume after await #1
    out.push('after-await-1');
    enqueue(() => out.push('after-await-2')); // resume after await #2
  });
}
out.push('sync-before');
task();
out.push('sync-after');
// A competing .then(other-1).then(other-2) chain started in the same tick.
enqueue(() => { out.push('other-1'); enqueue(() => out.push('other-2')); });
while (microQ.length) microQ.shift()(); // drain FIFO; the two interleave by tick
console.log(out.join(' '));
